// Alert when a model's average cache hit rate drops below a threshold.
// cache_hit_rate is a ratio (0.0–1.0). Threshold of 0.2 = 20%.
// Adjust the threshold in the final WHERE clause as needed.
FROM metrics-openrouter.performance-*
| WHERE openrouter.performance.cache_hit_rate IS NOT NULL
| STATS avg_cache_hit_rate = AVG(openrouter.performance.cache_hit_rate) BY openrouter.performance.model
| WHERE avg_cache_hit_rate < 0.2
